def split_matches(rows,train_ids,val_ids,test_ids):
    groups={'train':set(train_ids),'val':set(val_ids),'test':set(test_ids)}
    if groups['train']&groups['val'] or groups['train']&groups['test'] or groups['val']&groups['test']:
        raise ValueError('Overlapping match IDs')
    result={name:[] for name in groups}
    for row in rows:
        choices=[name for name,ids in groups.items() if row['match'] in ids]
        if len(choices)!=1:
            raise ValueError('Unassigned match')
        result[choices[0]].append(row)
    return result

